create table public.tonight_plans (id uuid primary key default gen_random_uuid(), owner_id uuid references public.profiles(id) on delete cascade, title text not null, starts_at timestamptz not null, status text not null default 'active' check(status in ('draft','active','completed','cancelled')), created_at timestamptz not null default now());
create table public.tonight_plan_stops (id uuid primary key default gen_random_uuid(), plan_id uuid not null references public.tonight_plans(id) on delete cascade, venue_id uuid references public.city_explore_venues(id), title text not null, arrival_at timestamptz not null, position smallint not null, unique(plan_id, position));
create table public.tonight_plan_members (plan_id uuid not null references public.tonight_plans(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, state text not null default 'invited' check(state in ('invited','accepted','arrived','declined','left')), primary key(plan_id,user_id));
create table public.nightguard_status (user_id uuid primary key references public.profiles(id) on delete cascade, enabled boolean not null default false, monitoring_until timestamptz, trusted_contact_count smallint not null default 0, updated_at timestamptz not null default now());
alter table public.tonight_plans enable row level security; alter table public.tonight_plan_stops enable row level security; alter table public.tonight_plan_members enable row level security; alter table public.nightguard_status enable row level security;
create policy "members can read plans" on public.tonight_plans for select to authenticated using(owner_id=auth.uid() or exists(select 1 from public.tonight_plan_members m where m.plan_id=id and m.user_id=auth.uid()));
create policy "members can read stops" on public.tonight_plan_stops for select to authenticated using(exists(select 1 from public.tonight_plans p where p.id=plan_id and p.owner_id=auth.uid()) or exists(select 1 from public.tonight_plan_members m where m.plan_id=tonight_plan_stops.plan_id and m.user_id=auth.uid()));
create policy "own nightguard status" on public.nightguard_status for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
